import csv
import sys


def count_nonempty(path):
    counts = {}
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        for row in reader:
            for col, value in row.items():
                if col is None:
                    continue
                if value is not None and value.strip() != "":
                    counts[col] = counts.get(col, 0) + 1
        if not counts and reader.fieldnames:
            counts = {col: 0 for col in reader.fieldnames}
    return counts


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(f"用法: python {sys.argv[0]} <csv文件>", file=sys.stderr)
        sys.exit(1)
    for col, count in count_nonempty(sys.argv[1]).items():
        print(f"{col}\t{count}")
